#[test]
fn test_tdf2_process_block_matches_single() {
    let mut single = Biquad::new(BiquadFilterType::Peak, 500.0, 48000.0, 4.0, 10.0);
    single.use_tdf2 = true;
    let mut block = Biquad::new(BiquadFilterType::Peak, 500.0, 48000.0, 4.0, 10.0);
    block.use_tdf2 = true;
    let input: Vec<f64> = (0..256).map(|i| (i as f64 * 0.05).sin()).collect();
    let single_out: Vec<f64> = input.iter().map(|&x| single.process(x)).collect();
    let mut block_buf = input.clone();
    block.process_block(&mut block_buf);
    for i in 0..256 {
        assert!(
            approx_eq(single_out[i], block_buf[i], 1e-12),
            "sample {}: single={} block={}",
            i,
            single_out[i],
            block_buf[i]
        );
    }
}

#[test]
fn test_result_matches_complex_response_magnitude() {
    let filters = [
        Biquad::new(BiquadFilterType::Lowpass, 500.0, 48000.0, 0.707, 0.0),
        Biquad::new(BiquadFilterType::Highpass, 2000.0, 48000.0, 0.707, 0.0),
        Biquad::new(BiquadFilterType::Peak, 1000.0, 48000.0, 2.0, 6.0),
        Biquad::new(BiquadFilterType::Lowshelf, 250.0, 48000.0, 0.707, 3.0),
        Biquad::new(BiquadFilterType::Highshelf, 6000.0, 48000.0, 0.707, -4.0),
    ];
    let freqs = [20.0, 100.0, 500.0, 1000.0, 4000.0, 12000.0, 20000.0];

    for filter in filters {
        for freq in freqs {
            let fast = filter.result(freq);
            let exact = filter.complex_response(freq).norm();
            assert!(
                approx_eq(fast, exact, 1e-9),
                "result({freq})={fast} should match complex_response norm {exact}"
            );
        }
    }
}

#[test]
fn test_coefficients_and_lerp() {
    let f1 = Biquad::new(BiquadFilterType::Peak, 1000.0, 48000.0, 1.0, 0.0);
    let f2 = Biquad::new(BiquadFilterType::Peak, 1000.0, 48000.0, 1.0, 12.0);
    let c1 = f1.coefficients();
    let c2 = f2.coefficients();
    let lerp0 = c1.lerp(&c2, 0.0);
    assert!(approx_eq(lerp0.b0, c1.b0, 1e-15));
    assert!(approx_eq(lerp0.a1, c1.a1, 1e-15));
    let lerp1 = c1.lerp(&c2, 1.0);
    assert!(approx_eq(lerp1.b0, c2.b0, 1e-15));
    assert!(approx_eq(lerp1.a1, c2.a1, 1e-15));
    let lerp_mid = c1.lerp(&c2, 0.5);
    assert!(approx_eq(lerp_mid.b0, (c1.b0 + c2.b0) / 2.0, 1e-15));
}

#[test]
fn test_process_with_coefficients_matches_normal() {
    let mut f1 = Biquad::new(BiquadFilterType::Peak, 1000.0, 48000.0, 2.0, 6.0);
    let mut f2 = Biquad::new(BiquadFilterType::Peak, 1000.0, 48000.0, 2.0, 6.0);
    let coeffs = f2.coefficients();
    for i in 0..500 {
        let x = (i as f64 * 0.1).sin();
        let y1 = f1.process(x);
        let y2 = f2.process_with_coefficients(x, &coeffs);
        assert!(
            approx_eq(y1, y2, 1e-12),
            "sample {}: normal={} with_coeffs={}",
            i,
            y1,
            y2
        );
    }
}

#[test]
fn test_coefficients_finite_for_all_filter_types() {
    let types = [
        BiquadFilterType::Lowpass,
        BiquadFilterType::Highpass,
        BiquadFilterType::HighpassVariableQ,
        BiquadFilterType::Bandpass,
        BiquadFilterType::Notch,
        BiquadFilterType::Peak,
        BiquadFilterType::Lowshelf,
        BiquadFilterType::Highshelf,
        BiquadFilterType::AllPass,
        BiquadFilterType::LowshelfOrf,
        BiquadFilterType::HighshelfOrf,
        BiquadFilterType::PeakMatched,
    ];
    for &ft in &types {
        let bq = Biquad::<f64>::new(ft, 1000.0, 48000.0, 1.0, 0.0);
        let c = bq.coefficients();
        assert!(
            f64::is_finite(c.b0),
            "{}: b0 should be finite",
            ft.short_name()
        );
        assert!(
            f64::is_finite(c.b1),
            "{}: b1 should be finite",
            ft.short_name()
        );
        assert!(
            f64::is_finite(c.b2),
            "{}: b2 should be finite",
            ft.short_name()
        );
        assert!(
            f64::is_finite(c.a1),
            "{}: a1 should be finite",
            ft.short_name()
        );
        assert!(
            f64::is_finite(c.a2),
            "{}: a2 should be finite",
            ft.short_name()
        );
        // With these benign parameters the a0 guard should not trigger.
        let identity = c.b0 == 1.0 && c.b1 == 0.0 && c.b2 == 0.0 && c.a1 == 0.0 && c.a2 == 0.0;
        assert!(
            !identity,
            "{}: coefficients should not be identity fallback",
            ft.short_name()
        );
    }
}

#[test]
fn test_update_params_recomputes_for_all_filter_types() {
    let mut bq = Biquad::<f64>::new(BiquadFilterType::Peak, 1000.0, 48000.0, 1.0, 0.0);
    let types = [
        BiquadFilterType::Lowpass,
        BiquadFilterType::Highpass,
        BiquadFilterType::HighpassVariableQ,
        BiquadFilterType::Bandpass,
        BiquadFilterType::Notch,
        BiquadFilterType::Peak,
        BiquadFilterType::Lowshelf,
        BiquadFilterType::Highshelf,
        BiquadFilterType::AllPass,
        BiquadFilterType::LowshelfOrf,
        BiquadFilterType::HighshelfOrf,
        BiquadFilterType::PeakMatched,
    ];
    for &ft in &types {
        bq.update_params(ft, 1000.0, 48000.0, 1.0, 0.0);
        assert_eq!(bq.filter_type, ft);
        let resp: f64 = bq.log_result(1000.0);
        assert!(
            f64::is_finite(resp),
            "{}: response should be finite after update_params",
            ft.short_name()
        );
    }
}
